//! Differential test: `parse_duration_seconds` / `duration_prefix_bytes_needed` against vectors generated by running the
//! original TypeScript (`tools/gen-duration-golden.mjs` -> `tests/data/duration_golden.json`). The inputs include every
//! truncation of the small fixtures and random byte flips, which is where an "out-of-range byte reads as 0" difference
//! would show up.

use beatseam_core::metadata::{duration_prefix_bytes_needed, parse_duration_seconds};
use serde_json::Value;

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn golden() -> Value {
    serde_json::from_str(include_str!("data/duration_golden.json")).unwrap()
}

#[test]
fn parse_duration_matches_the_typescript_on_every_vector() {
    let golden = golden();
    let cases = golden["cases"].as_array().unwrap();
    assert!(cases.len() > 300, "{} cases", cases.len());
    let mut with_duration = 0;
    for (i, case) in cases.iter().enumerate() {
        let (name, size) = (case["name"].as_str().unwrap(), case["size"].as_u64().unwrap());
        let bytes = unhex(case["hex"].as_str().unwrap());
        let got = parse_duration_seconds(&bytes, name, size);
        match (case["result"].as_f64(), got) {
            (None, None) => {}
            (Some(want), Some(got)) => {
                with_duration += 1;
                assert!((want - got).abs() <= want.abs() * 1e-12 + 1e-12, "case {i} {name} ({} bytes): TS {want}, Rust {got}", bytes.len());
            }
            (want, got) => panic!("case {i} {name} ({} bytes, size {size}): TS {want:?}, Rust {got:?}", bytes.len()),
        }
    }
    assert!(with_duration > 50, "only {with_duration} cases produced a duration - the fixtures are not exercising the parsers");
}

#[test]
fn duration_prefix_bytes_needed_matches_the_typescript() {
    let golden = golden();
    for case in golden["prefixCases"].as_array().unwrap() {
        let (name, want) = (case["name"].as_str().unwrap(), case["result"].as_u64().unwrap() as usize);
        assert_eq!(duration_prefix_bytes_needed(&unhex(case["hex"].as_str().unwrap()), name), want, "{name}");
    }
}
